import Foundation
@propertyWrapper
struct Trimmed {
    private var value: String
    private var trimmed: Bool
    init(wrappedValue: String) {
        value = wrappedValue.trimmingCharacters(in: .whitespaces)
        trimmed = value != wrappedValue
    }
    var wrappedValue: String {
        get { value }
        set {
            value = newValue.trimmingCharacters(in: .whitespaces)
            trimmed = value != newValue
        }
    }
    var projectedValue: Bool { trimmed }
}
struct Playlist {
    @Trimmed var name = " Утро "
}
var list = Playlist()
print(list.name, list.$name)
list.name = "Вечер"
print(list.name, list.$name)

Утро true
Вечер false

Та же схема, что у Clamped, на новом правиле: `init(wrappedValue:)` обрабатывает начальное значение, setter `wrappedValue` — каждую запись, `projectedValue` через `$name` сообщает, сработало ли правило в последний раз.

